"""json2csv: Convert JSON array from stdin to CSV on stdout.

Usage: cat data.json | python3 json2csv
"""

import json
import sys


def escape_csv(value):
    """Escape a value for CSV output."""
    s = str(value)
    # If the value contains commas, double quotes, or newlines, wrap in quotes
    if "," in s or '"' in s or "\n" in s or "\r" in s:
        # Double any double quotes inside
        s = s.replace('"', '""')
        s = f'"{s}"'
    return s


def json_to_csv(json_data, output=sys.stdout, error=sys.stderr):
    """Parse JSON array and write CSV to output."""
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        error.write(f"Error: Invalid JSON - {e}\n")
        return 1

    if not isinstance(data, list):
        error.write("Error: Input must be a JSON array\n")
        return 1

    if not data:
        return 0

    # Collect all keys from all objects (preserving order)
    seen = {}
    keys = []
    for obj in data:
        if isinstance(obj, dict):
            for k in obj:
                if k not in seen:
                    seen[k] = len(keys)
                    keys.append(k)

    # Write header
    output.write(",".join(escape_csv(k) for k in keys))
    output.write("\n")

    # Write rows
    for obj in data:
        if not isinstance(obj, dict):
            row = [""] * len(keys)
            row[0] = escape_csv(str(obj))
            output.write(",".join(row))
            output.write("\n")
            continue

        row = [""] * len(keys)
        for k, v in obj.items():
            if k in seen:
                idx = seen[k]
                # Nested objects/arrays get stringified
                if isinstance(v, (dict, list)):
                    row[idx] = escape_csv(json.dumps(v, ensure_ascii=False))
                elif v is None:
                    row[idx] = ""
                else:
                    row[idx] = escape_csv(v)
        output.write(",".join(row))
        output.write("\n")

    return 0


def main():
    input_data = sys.stdin.read()
    return json_to_csv(input_data)


if __name__ == "__main__":
    sys.exit(main())
"}

